function a(r){return r?r.replace(/[_-]/g," ").replace(/([a-z])([A-Z])/g,"$1 $2").split(" ").filter(n=>n.length>0).map(n=>n.charAt(0).toUpperCase()+n.slice(1)).join(" "):""}function u(r){if("group"in r&&r.group){const n=r.group;return n.display_name||a(n.name)}const t=r;return t.display_name||a(t.name)}function s(r){return!r||r.length<=8?r||"":`${r.substring(0,4)}...${r.substring(r.length-4)}`}function e(r){return r?r.split(",").map(t=>s(t.trim())).join(", "):""}export{s as a,u as g,e as m};
